import{_ as e,o as a,c as t,a2 as i}from"./chunks/framework.gtmkOXzY.js";const g=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"ms-flightsim/installation.md","filePath":"ms-flightsim/installation.md","lastUpdated":null}'),n={name:"ms-flightsim/installation.md"};function o(l,s,r,c,p,d){return a(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Drop the folders in, add the ensure lines in the right order, and start the server. The database creates its own tables on first start.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><p>Extract the download into your <code>resources</code> folder.</p></li><li><p>Add the ensure lines to <code>server.cfg</code>.</p><div class="warning custom-block"><p class="custom-block-title">Order matters</p><p>The asset resources start first and <strong>MS_FlightSim always starts last</strong>, after your framework.</p></div><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ensure oxmysql</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ensure ox_lib</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ensure qbx_core          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or qb-core / es_extended</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ensure ox_inventory, ox_target, your keys and fuel scripts here</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ensure ms100</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ensure MS_FlightSim_MSE</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ensure MS_FlightSim_LSIA</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ensure ms_aircraft_core   # only with the MS41s water bomber</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ensure ms41s</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ensure MS_FlightSim</span></span></code></pre></div></li><li><p><strong>Database</strong>: nothing to do. Every table is created automatically on first start. <code>sql/schema.sql</code> is included if you prefer to import by hand.</p></li><li><p><strong>Pilot job</strong>: create a <code>pilot</code> job in your framework, or switch to open access so nobody needs a job (see <a href="./configuration#pilot-job-or-open-access">Configuration</a>).</p></li><li><p><strong>Discord logs (optional)</strong>: add the webhook as a convar in <code>server.cfg</code>. Use <code>set</code>, never <code>setr</code>, so players can&#39;t read it.</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">set ms_flightsim_webhook </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://discord.com/api/webhooks/...&quot;</span></span></code></pre></div></li><li><p><strong>Start the server and read the console.</strong> You should see your framework detected and a line saying whether the pilot job is required or open access is on.</p></li><li><p><strong>In game</strong>, run <code>/adminps</code> to open the admin panel. Place the ATC tower console with <code>/atcscope place</code> or the panel&#39;s <strong>Screens</strong> tab. The LSIA ground-services board is already placed.</p></li></ol><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">ATC voice</p><p>The ATC voice ships pre-recorded in <code>html/sounds/atc/cache</code> (about 31 MB). Upload the whole folder: it needs no API key and costs nothing to run.</p></div><div class="danger custom-block"><p class="custom-block-title">Never restart the map with players online</p><p>Restarting <code>MS_FlightSim_LSIA</code> (or <code>MS_FlightSim_MSE</code>) while players are connected crashes their game. Start them once and leave them running; restarting <code>MS_FlightSim</code> itself is safe.</p></div><div class="warning custom-block"><p class="custom-block-title">Debug mode</p><p>Keep <code>Config.Debug = false</code> on a live server. With it on, the pilot-job, rank and rating checks are skipped.</p></div>`,8)])])}const k=e(n,[["render",o]]);export{g as __pageData,k as default};
